&lt;p&gt;&lt;strong&gt;2986 - Account Director, Commerce - UK&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About&amp;nbsp;EssenceMediacom: A Leading&amp;nbsp;WPP Media&amp;nbsp;Brand&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;EssenceMediacom&amp;nbsp;is a new breed of media agency. Grounded in analytics &amp;amp; insights and powered by data &amp;amp; technology, we believe in the power of media and creative to drive breakthroughs for the world’s best brands. We help clients understand the modern marketing paradox and discover the breakthroughs brands need to win with their consumers. We are designed for the new communications economy — built on data &amp;amp; technology, built for people &amp;amp; algorithms, built around diverse schools of thought, built to test &amp;amp; learn at scale, and, crucially, built to&amp;nbsp;evolve.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Role&amp;nbsp;Summary and Impact&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The Role:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We’re&amp;nbsp;seeking an&amp;nbsp;experienced&amp;nbsp;Retail&amp;nbsp;Media&amp;nbsp;Account Director to come and join the growing community in&amp;nbsp;WPP Media’s&amp;nbsp;Commerce Practice.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We’re&amp;nbsp;looking for a skilled&amp;nbsp;Commerce Media Account Director&amp;nbsp;to lead&amp;nbsp;key&amp;nbsp;client accounts across Amazon Sponsored Ads, Amazon DSP,&amp;nbsp;CitrusAd,&amp;nbsp;Criteo&amp;nbsp;&amp;amp; Kevel.&amp;nbsp;You’ll&amp;nbsp;be&amp;nbsp;a&amp;nbsp;senior&amp;nbsp;member of the team, responsible for translating&amp;nbsp;your&amp;nbsp;client’s&amp;nbsp;business&amp;nbsp;objectives&amp;nbsp;into media strategies, while also ensuring operational excellence and coaching your team&amp;nbsp;of commerce media specialists.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Responsibilities:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Act as&amp;nbsp;the&amp;nbsp;day&amp;nbsp;to&amp;nbsp;day&amp;nbsp;senior&amp;nbsp;contact for key clients,&amp;nbsp;providing&amp;nbsp;strategic guidance across Amazon&amp;nbsp;and&amp;nbsp;additional&amp;nbsp;retailers utilising&amp;nbsp;CitrusAd,&amp;nbsp;Criteo&amp;nbsp;&amp;amp; Kevel.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
